// ── Observe every phase of the browser pipeline ──────────────
window.addEventListener('load', () => {
  const nav = performance.getEntriesByType('navigation')[0];

  // Each property is a DOMHighResTimeStamp (ms since navigationStart)
  const phases = {
    'DNS lookup':        nav.domainLookupEnd  - nav.domainLookupStart,
    'TCP connect':       nav.connectEnd       - nav.connectStart,
    'TLS negotiate':     nav.secureConnectionStart > 0
                           ? nav.connectEnd - nav.secureConnectionStart
                           : 0,
    'Request queued':    nav.requestStart     - nav.fetchStart,
    'TTFB':              nav.responseStart    - nav.requestStart,
    'Response download': nav.responseEnd      - nav.responseStart,
    'DOM parsing':       nav.domInteractive   - nav.responseEnd,
    'Sub-resources':     nav.domContentLoadedEventStart - nav.domInteractive,
    'Load event':        nav.loadEventEnd     - nav.loadEventStart,
    'Total':             nav.loadEventEnd     - nav.fetchStart,
  };

  console.table(
    Object.fromEntries(
      Object.entries(phases).map(([k, v]) => [k, `${v.toFixed(1)} ms`])
    )
  );
});

// ── Detect render-blocking resources ─────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  const resources = performance.getEntriesByType('resource');

  // renderBlockingStatus is available in Chrome 107+
  const blocking = resources.filter(
    r => r.renderBlockingStatus === 'blocking'
  );

  if (blocking.length > 0) {
    console.warn(
      'Render-blocking resources detected:',
      blocking.map(r => ({ url: r.name, duration: r.duration.toFixed(1) + 'ms' }))
    );
  }
});

// ── Measure Core Web Vitals programmatically ──────────────────
const observer = new PerformanceObserver(list => {
  for (const entry of list.getEntries()) {
    if (entry.entryType === 'largest-contentful-paint') {
      console.log('LCP:', entry.startTime.toFixed(0), 'ms');
    }
    if (entry.entryType === 'layout-shift' && !entry.hadRecentInput) {
      console.log('CLS contribution:', entry.value.toFixed(4));
    }
  }
});
observer.observe({ entryTypes: ['largest-contentful-paint', 'layout-shift'] });

// ── Inject resource hints dynamically ────────────────────────
// Useful when you know an origin will be needed before HTML discovery
function preconnect(origin) {
  const link = document.createElement('link');
  link.rel = 'preconnect';
  link.href = origin;
  link.crossOrigin = 'anonymous';
  document.head.appendChild(link);
}

// Warm up the connection to your API server before any fetch() calls
preconnect('https://api.example.com');

sections.content:
**Layout** (historically called **Reflow** in Firefox) is the phase where the browser computes the precise position and size of every element in the render tree. Inputs are: the viewport dimensions, the CSS box model properties (width, height, padding, border, margin), and the positioning scheme (flow, flex, grid, absolute, sticky).

Layout is one of the most computationally expensive steps. A single CSS property change that affects geometry — changing `width`, adding `padding`, toggling `display` — can trigger a **reflow** that invalidates and recomputes large portions of the layout tree. **Layout thrashing** occurs when JavaScript alternately reads and writes layout-affecting properties in a loop, forcing the browser to recompute layout synchronously on every write:

```js
// BAD: forces reflow on every iteration
for (const el of elements) {
  el.style.width = el.offsetWidth + 10 + 'px'; // read offsetWidth → force reflow, then write
}

// GOOD: batch reads first, then writes
const widths = elements.map(el => el.offsetWidth); // one reflow
for (let i = 0; i < elements.length; i++) {
  elements[i].style.width = widths[i] + 10 + 'px'; // writes only
}
```

Modern browsers implement **incremental layout**: only the subtrees that are marked dirty are re-laid out. But if the root element changes, the entire document is re-laid out. **Flexbox** and **CSS Grid** have their own layout algorithms that are generally efficient, though a flex container with many items that change dynamically can be expensive.

**Intrinsic sizing** (using `width: fit-content`, `min-content`, `max-content`) and **aspect-ratio** help the browser reserve space for elements before their content loads, reducing layout shifts — a key factor in the **Cumulative Layout Shift (CLS)** Core Web Vital.

