// ── Avoid layout thrashing: batch DOM reads before writes ─────
function resizeElementsBadly(elements) {
  // Each iteration: read offsetWidth (forces reflow) then write style
  // Browser cannot batch: every write invalidates cached layout
  elements.forEach(el => {
    const w = el.offsetWidth;           // FORCES synchronous reflow
    el.style.width = (w + 10) + 'px';   // invalidates layout again
  });
}

function resizeElementsWell(elements) {
  // Phase 1: read all widths in one pass (one reflow total)
  const widths = Array.from(elements, el => el.offsetWidth);

  // Phase 2: write all widths (no reads — no forced reflow)
  elements.forEach((el, i) => {
    el.style.width = (widths[i] + 10) + 'px';
  });
}

// ── Prefer transform over position for animation ──────────────
// BAD: triggers layout + paint every frame (slow)
function animateBad(el) {
  let x = 0;
  function tick() {
    x += 2;
    el.style.left = x + 'px';  // forces Layout every frame
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

// GOOD: only compositor step — no Layout, no Paint
function animateGood(el) {
  let x = 0;
  function tick() {
    x += 2;
    el.style.transform = `translateX(${x}px)`;  // Composite only
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

// ── Use requestAnimationFrame for visual updates ──────────────
// rAF batches updates to the next paint cycle, keeping JS + DOM
// writes in sync with the browser's rendering schedule.
// Never use setTimeout(fn, 0) for animations — it is asynchronous
// and can fire at any point in the frame, causing jank.
function smoothProgress(progressEl, targetWidth) {
  let current = 0;
  function step() {
    current = Math.min(current + 2, targetWidth);
    progressEl.style.width = current + '%';
    if (current < targetWidth) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

// ── Force GPU layer for an element ────────────────────────────
// Use will-change to hint the browser about upcoming animations
// Do not apply to everything — each layer consumes GPU memory
function promoteToGPULayer(el) {
  el.style.willChange = 'transform';  // browser pre-creates GPU layer
}

function demoteFromGPULayer(el) {
  el.style.willChange = 'auto';  // release GPU layer when animation ends
}

// ── Script loading strategy reference ────────────────────────
//
// <script src="app.js">              — blocks parser + render until done
// <script src="app.js" defer>        — parallel download, runs after DOM
// <script src="app.js" async>        — parallel download, runs ASAP
// <script type="module" src="app.js"> — deferred by default, ES module
//
// DOMContentLoaded fires AFTER defer scripts finish
// window.load fires AFTER all resources (including images)
//
// ── Preload critical resources in HTML <head> ─────────────────
//
// Fonts (critical — prevents invisible text during load)
// <link rel="preload" href="/inter.woff2" as="font" crossorigin>
//
// LCP image (hero image appears faster)
// <link rel="preload" href="/hero.webp" as="image">
//
// ── Measure Largest Contentful Paint (Core Web Vital) ────────
const lcpObserver = new PerformanceObserver(list => {
  const entries = list.getEntries();
  const last = entries[entries.length - 1];  // last = most recent large element
  console.log('LCP element:', last.element);
  console.log('LCP time:', last.startTime.toFixed(0) + 'ms');
  // Google thresholds: Good < 2500ms, Needs Improvement < 4000ms, Poor >= 4000ms
  const rating = last.startTime < 2500 ? 'Good'
    : last.startTime < 4000 ? 'Needs Improvement'
    : 'Poor';
  console.log('LCP rating:', rating);
});
lcpObserver.observe({ entryTypes: ['largest-contentful-paint'] });

// ── Measure Interaction to Next Paint (INP, replaces FID) ────
const inpObserver = new PerformanceObserver(list => {
  for (const entry of list.getEntries()) {
    if (entry.interactionId) {
      const delay = entry.processingStart - entry.startTime;
      console.log(`Input delay: ${delay.toFixed(1)}ms (target < 100ms)`);
    }
  }
});
inpObserver.observe({ entryTypes: ['event'], durationThreshold: 16 });

// ── Inline critical CSS pattern (done at build time) ─────────
// This is typically handled by tools like Critters or Critical (npm)
// The manual pattern is:
// 1. Identify CSS needed for above-the-fold rendering
// 2. Embed it in <style> in <head>
// 3. Load full stylesheet asynchronously:
function loadCSS(href) {
  const link = document.createElement('link');
  link.rel = 'stylesheet';
  link.href = href;
  link.media = 'print';  // trick: 'print' = non-blocking
  link.onload = function() { this.media = 'all'; };  // swap to 'all' on load
  document.head.appendChild(link);
}
